import java.util.*;
import java.io.*;

public class Main {
    static final int MOD = 1000000007;
    static int n;
    static int totalStates = 0;
    static int[] countBits = new int[1 << 8]; // maximum n=8 for safety
    static int[] indexMap = new int[1 << 8];
    static int[][] f = new int[10][1 << 8]; // assuming n <= 8
    static List<List<Integer>> groups = new ArrayList<>();
    static Map<Pair, Integer> memo = new HashMap<>();

    static class Pair {
        int layer;
        long mask;

        Pair(int layer, long mask) {
            this.layer = layer;
            this.mask = mask;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Pair)) return false;
            Pair pair = (Pair) o;
            return layer == pair.layer && mask == pair.mask;
        }

        @Override
        public int hashCode() {
            return Objects.hash(layer, mask);
        }
    }

    static int modExp(int base, int exp) {
        long res = 1;
        long b = base;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                res = (res * b) % MOD;
            }
            b = (b * b) % MOD;
            exp >>= 1;
        }
        return (int) res;
    }

    static int solveDP(int layer, long mask) {
        if (mask == 0) return 0;
        if (layer == n) return 1;
        Pair key = new Pair(layer, mask);
        if (memo.containsKey(key)) return memo.get(key);

        totalStates++;
        int result = 0;
        int limit = (1 << n) - 1;
        for (int subset = 1; subset <= limit; subset++) {
            long next_mask = 0;
            for (int k = 0; k < groups.get(layer).size(); k++) {
                if ((mask & (1L << k)) == 0) continue;
                int prev = groups.get(layer).get(k);
                for (int l = 0; l < n; l++) {
                    if ((subset & (1 << l)) != 0 && (prev & (1 << l)) ) {
                        // do nothing, just continue
                    } else if ((subset & (1 << l)) != 0 && (prev & (1 << l)) == 0) {
                        // find the index of prev | (1 << l)
                        int val = prev | (1 << l);
                        int idx = indexMap[val];
                        next_mask |= 1L << idx;
                    }
                }
            }
            long temp = ((long)f[layer][subset] * solveDP(layer + 1, next_mask)) % MOD;
            result = (result + (int)temp) % MOD;
        }
        memo.put(key, result);
        return result;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        n = Integer.parseInt(br.readLine());
        int inv100 = modExp(100, MOD - 2);
        for (int i = 0; i < n; i++) {
            Arrays.fill(f[i], 1);
            StringTokenizer st = new StringTokenizer(br.readLine());
            for (int j = 0; j < n; j++) {
                int P = Integer.parseInt(st.nextToken());
                int p1 = (int)((long)P * inv100 % MOD);
                int p0 = (MOD + 1 - p1) % MOD;
                for (int k = (1 << j) - 1; k >= 0; k--) {
                    f[i][k | (1 << j)] = (int)((long)f[i][k] * p1 % MOD);
                    f[i][k] = (int)((long)f[i][k] * p0 % MOD);
                }
            }
        }
        int size = 1 << n;
        for (int i = 0; i < size; i++) {
            countBits[i] = Integer.bitCount(i);
        }
        for (int i = 0; i < size; i++) {
            int c = countBits[i];
            while (groups.size() <= c) {
                groups.add(new ArrayList<>());
            }
            groups.get(c).add(i);
        }
        for (int i = 0; i < size; i++) {
            int c = countBits[i];
            indexMap[i] = groups.get(c).size() - 1;
        }
        System.out.println(solveDP(0, 1L));
    }
}
